from scipy.optimize import least_squares
TSS=np.sum((sigma-sigma.mean())**2)
Tf={
 'Tq': lambda a: T**a[0],
 'exp(-aT)T^q': lambda a: np.exp(-a[0]*T)*T**a[1],
 'bose 1/(exp(aT)-1)': lambda a: 1/(np.exp(a[0]*T)-1),
 'exp(-a/T)': lambda a: np.exp(-a[0]/T),
 'tanh(aT)': lambda a: np.tanh(a[0]*T),
 '1/(1+aT)': lambda a: 1/(1+a[0]*T),
 'exp(a/T)*': lambda a: np.exp(a[0]/T)*T**a[1],
}
Ef={
 'eps^p':lambda b: eps**b[0],
 'eps^p exp(-b eps)': lambda b: eps**b[0]*np.exp(-b[1]*eps),
 'eps^p tanh(b eps)': lambda b: eps**b[0]*np.tanh(b[1]*eps),
 'eps^p*(1+b eps)': lambda b: eps**b[0]*(1+b[1]*eps),
}
out=[]
for tn,tf in Tf.items():
  for en,ef in Ef.items():
    nT = 2 if tn in ('exp(-aT)T^q','exp(a/T)*') else 1
    nE = 1 if en=='eps^p' else 2
    best=None
    for trial in range(6):
        rng=np.random.default_rng(trial)
        p0=np.concatenate([[0.2,0.3],rng.uniform(0.2,1.5,nT),rng.uniform(0.2,1.5,nE)])
        def rr(p):
            a=p[2:2+nT]; b=p[2+nT:]
            with np.errstate(all='ignore'):
                X=tf(a)*ef(b)
                M=np.column_stack([eps**2, np.exp(-p[0]*T)*eps**1.5, np.tanh(p[1]*eps), X])
                c,*_=np.linalg.lstsq(M,sigma,rcond=None); r=M@c-sigma
            return np.nan_to_num(r,nan=1e3,posinf=1e3,neginf=-1e3)
        try:
            s=least_squares(rr,p0)
            if best is None or s.cost<best.cost: best=s
        except Exception: pass
    if best is not None: out.append((best.cost*2/TSS,tn,en,np.round(best.x,4)))
for o in sorted(out,key=lambda z:z[0])[:6]: print(o)

